# ORFs in all 6 frames
comp_rev = {'A':'T','T':'A','G':'C','C':'G'}
rc = ''.join(comp_rev[b] for b in reversed(seq))
stop = {'TAA','TAG','TGA'}

def find_orfs(s, label):
    orfs = []
    for frame in range(3):
        i = frame
        start = None
        for j in range(frame, len(s)-2, 3):
            cod = s[j:j+3]
            if cod == 'ATG' and start is None:
                start = j
            if cod in stop:
                if start is not None:
                    orfs.append((j+3-start, start, j+3, frame, label))
                    start = None
        # trailing ORF to end
        if start is not None:
            orfs.append((len(s)-start, start, len(s), frame, label))
    return orfs

orfs = find_orfs(seq, 'fwd') + find_orfs(rc, 'rev')
orfs.sort(reverse=True)
print("\nTop ORFs (length bp, start, end, frame, strand):")
for o in orfs[:15]:
