    lines = f.read().split("\n")
for l in lines[1:]:
    seq += l.strip()
seq = seq.upper()
n=len(seq)
import random

def longest_stopfree(s):
    stops={'TAA','TAG','TGA'}
    best=0;bestpos=0
    for f in range(3):
        run=0;rstart=f
        for j in range(f,len(s)-2,3):
            if s[j:j+3] in stops:
                if run>best: best=run;bestpos=rstart
                run=0;rstart=j+3
            else: run+=3
        if run>best: best=run;bestpos=rstart
    return best,bestpos

print("longest stop-free stretch (bp) in real seq:", longest_stopfree(seq))

# shuffle test
random.seed(1)
vals=[]
for _ in range(20):
    l=list(seq); random.shuffle(l); s2=''.join(l)
    vals.append(longest_stopfree(s2)[0])
print("shuffled longest stop-free: mean %.0f max %d"%(sum(vals)/len(vals), max(vals)))

# approximate repeats: seed with 24-mer, allow up to 3 mismatches over 40bp window
def mism(a,b): return sum(1 for x,y in zip(a,b) if x!=y)
L=40; K=24
seeds={}
hits=[]
for i in range(n-K+1):
    k=seq[i:i+K]
    for j in seeds.get(k,[]):
        if i-j>=L:
            if mism(seq[j:j+L], seq[i:i+L])<=3:
                hits.append((j,i,mism(seq[j:j+L],seq[i:i+L])))
    seeds.setdefault(k,[]).append(i)
print("\napproximate repeats (>=40bp, <=3 mism):", len(hits))
for h in hits[:20]: print(h)
